PI = 3.141592653589793

for _ in range(12):
    pose = get_pose()
    x, y, h = pose['x'], pose['y'], pose['heading_deg']

    wp = get_waypoint()
    g = get_goal()
    wx, wy = wp['x'], wp['y']
    gx, gy = g['x'], g['y']

    dist_way = distance_to(wx, wy)
    dist_goal = distance_to(gx, gy)

    if dist_way > 0.6:
        target_h = heading_to(wx, wy)
    else:
        target_h = heading_to(gx, gy)

    error = target_h - h
    if error > 180:
        error -= 360
    elif error < -180:
        error += 360

    wz = error * (PI / 180.0) / 5.0
    if wz > 1.0:
        wz = 1.0
    if wz < -1.0:
        wz = -1.0

    if dist_way > 0.6:
        vx = 0.3
        vy = 0.0
    else:
        if dist_goal < 0.3:
            vx = 0.1
        else:
            vx = 0.3
        vy = 0.0

    result = walk(vx, vy, wz, 5)
    if result['fell']:
        stop(5)
        break
    if result['dist_goal_m'] <= 0.5:
        stop(2)
        break

